// --- Bit trick reference block ---

// Power of 2 check
function isPowerOfTwo(n) {
  return n > 0 && (n & (n - 1)) === 0;
}

// Isolate lowest set bit (used in Fenwick Trees)
function lowestSetBit(n) {
  return n & (-n);
}

// Remove lowest set bit
function removeLowestSetBit(n) {
  return n & (n - 1);
}

// Count set bits (Brian Kernighan)
function popcount(n) {
  let count = 0;
  while (n) {
    count++;
    n &= n - 1; // drop the lowest set bit each time
  }
  return count;
}

// Find single non-duplicate (all others appear twice)
function singleNumber(nums) {
  let xor = 0;
  for (const n of nums) xor ^= n; // pairs cancel out
  return xor;
}

// Test bit k (0-indexed from right)
function testBit(n, k) {
  return (n >> k) & 1;
}

// Set bit k
function setBit(n, k) {
  return n | (1 << k);
}

// Clear bit k
function clearBit(n, k) {
  return n & ~(1 << k);
}

// Toggle bit k
function toggleBit(n, k) {
  return n ^ (1 << k);
}
